<?php require_once 'layout.php'; require_auth(); if(is_admin()) redirect(BASE_URL.'/admin.php');
$id=(int)($_GET['id']??0);$s=db()->prepare('SELECT p.*,c.name cat FROM products p JOIN categories c ON c.id=p.category_id WHERE p.id=?');$s->execute([$id]);$p=$s->fetch(); if(!$p) redirect(BASE_URL.'/products.php');
if($_SERVER['REQUEST_METHOD']==='POST'){
 if(isset($_POST['cart'])){$q=max(1,(int)$_POST['qty']); if($q>$p['stock']){$q=$p['stock'];} $ex=db()->prepare('SELECT quantity FROM cart WHERE user_id=? AND product_id=?');$ex->execute([$_SESSION['user_id'],$id]);$cur=(int)$ex->fetchColumn(); if($cur+$q>$p['stock']){$q=max(0,$p['stock']-$cur);} if($q>0){db()->prepare('INSERT INTO cart(user_id,product_id,quantity) VALUES(?,?,?) ON CONFLICT(user_id,product_id) DO UPDATE SET quantity=quantity+excluded.quantity')->execute([$_SESSION['user_id'],$id,$q]); flash('Ürün sepete eklendi.');} else flash('Stok sınırına ulaştın.'); redirect(BASE_URL.'/product.php?id='.$id);}
 if(isset($_POST['fav'])){db()->prepare('INSERT OR IGNORE INTO favorites(user_id,product_id) VALUES(?,?)')->execute([$_SESSION['user_id'],$id]); flash('Favorilere eklendi.'); redirect(BASE_URL.'/product.php?id='.$id);}
 if(isset($_POST['review'])){$b=db()->prepare('SELECT COUNT(*) FROM order_items oi JOIN orders o ON o.id=oi.order_id WHERE o.user_id=? AND oi.product_id=?');$b->execute([$_SESSION['user_id'],$id]); if($b->fetchColumn()>0){db()->prepare('INSERT INTO reviews(user_id,product_id,rating,comment) VALUES(?,?,?,?) ON CONFLICT(user_id,product_id) DO UPDATE SET rating=excluded.rating, comment=excluded.comment, created_at=CURRENT_TIMESTAMP')->execute([$_SESSION['user_id'],$id,(int)$_POST['rating'],trim($_POST['comment']??'')]); flash('Değerlendirmen kaydedildi.');} else flash('Sadece satın aldığın ürünü değerlendirebilirsin.'); redirect(BASE_URL.'/product.php?id='.$id);}
}
$imgs=db()->prepare('SELECT * FROM product_images WHERE product_id=? ORDER BY id');$imgs->execute([$id]);$imgs=$imgs->fetchAll(); if(!$imgs)$imgs=[['image_path'=>'logo.jpg']];
$rev=db()->prepare('SELECT r.*,u.name FROM reviews r JOIN users u ON u.id=r.user_id WHERE product_id=? ORDER BY r.created_at DESC');$rev->execute([$id]);$reviews=$rev->fetchAll();
$can=db()->prepare('SELECT COUNT(*) FROM order_items oi JOIN orders o ON o.id=oi.order_id WHERE o.user_id=? AND oi.product_id=?');$can->execute([$_SESSION['user_id'],$id]);$canReview=$can->fetchColumn()>0;
page_header($p['name']); ?>
<div class="card"><div class="gallery"><div class="thumbs"><?php foreach($imgs as $im): $src=UPLOAD_URL.'/'.h($im['image_path']); ?><img src="<?=$src?>" onclick="changeMain('<?=$src?>')"><?php endforeach; ?></div><img id="mainpic" class="mainpic" src="<?=UPLOAD_URL.'/'.h($imgs[0]['image_path'])?>" onclick="openImage(this.src)"></div></div>
<div class="grid" style="margin-top:18px"><section class="card"><span class="pill"><?=h($p['cat'])?></span><h1><?=h($p['name'])?></h1><p class="price"><?=money($p['price'])?></p><p>Stok: <b><?=h($p['stock'])?></b></p><p class="muted"><?=nl2br(h($p['description']))?></p><form method="post" class="actions"><input class="field" style="max-width:120px" type="number" name="qty" value="1" min="1" max="<?=$p['stock']?>"><button class="btn primary" name="cart">Sepete Ekle</button><button class="btn hot" name="fav">Favorilere Ekle</button></form></section><section class="card"><h2>Değerlendirmeler</h2><?php if($canReview): ?><form method="post"><select name="rating"><option value="5">5 yıldız</option><option value="4">4 yıldız</option><option value="3">3 yıldız</option><option value="2">2 yıldız</option><option value="1">1 yıldız</option></select><textarea name="comment" placeholder="Yorumun"></textarea><button class="btn primary" name="review">Değerlendir</button></form><?php else: ?><p class="muted">Bu ürünü satın aldıktan sonra değerlendirme yapabilirsin.</p><?php endif; ?><?php foreach($reviews as $r): ?><div class="card"><b><?=h($r['name'])?></b> · <?=str_repeat('★',(int)$r['rating'])?><p><?=h($r['comment'])?></p></div><?php endforeach; ?></section></div>
<div id="imgModal" class="modal" onclick="closeImage()"><span class="close">×</span><img id="modalImg"></div>
<?php page_footer(); ?>
